const router = $('Build Event Context').first().json;
const settings = $input.first()?.json || {};

const event = router.event || {};
const channel = router.channel || {};

const commentText = (event.message || '').trim();
const commenterName = event.from?.name || 'العميل';
const commenterId = event.from?.id || '';
const systemPrompt = settings.ai_system_prompt || '';

// 1. Separate action image assets from the Fixed Replies config stored in action_assets
const rawAssets = Array.isArray(settings.action_assets) ? settings.action_assets : [];
const actionAssets = rawAssets.filter(
  a => a && !a.is_config && a.id !== '__fixed_replies_config__' && a.name
);
const fixedConfig = rawAssets.find(
  a => a && (a.is_config === true || a.id === '__fixed_replies_config__')
) || {};

const fixedRepliesEnabled = Boolean(fixedConfig.enabled);
const normalFixedReplies = Array.isArray(fixedConfig.normal_replies) && fixedConfig.normal_replies.filter(Boolean).length > 0
  ? fixedConfig.normal_replies.map(r => String(r).trim()).filter(Boolean)
  : [
      'أهلاً بحضرتك يا فندم في تشيكن مراعي! 🍗 تم إرسال كل التفاصيل في رسائل الصفحة 📩',
      'منورنا يا فندم! 🌟 بعتنالك رسالة على الخاص حالاً بكل التفاصيل 🛵',
      'تحت أمرك يا فندم! راجع رسائل الماسنجر، فريقنا معاك هناك فوراً ❤️'
    ];

const actionsDescriptions = actionAssets
  .map(a => `- "${a.name}": ${a.description || a.label}`)
  .join('\n');
const allowedActionKeys = ['"normal"', ...actionAssets.map(a => `"${a.name}"`)].join(' | ');

// 2. Fixed DM & Complaint messages from dashboard
const fallbackDmMessage = (settings.fallback_dm_message || '').trim() || 'أهلاً بحضرتك يا فندم نورتنا! 🍗 تقدر تطلب أو تستفسر عن أي حاجة من هنا مباشرة 🛵';
const complaintPublicReply = (settings.complaint_public_reply || '').trim() || 'بنعتذر جداً لحضرتك يا فندم، يهمنا رضاك وتم التواصل معاك على الخاص لحل المشكلة فوراً 🙏';
const complaintDmMessage = (settings.complaint_dm_message || '').trim() || 'أهلاً بحضرتك يا فندم، بنعتذر جداً عن أي إزعاج. ممكن تبعتلنا رقم تليفونك وتفاصيل المشكلة وفريق خدمة العملاء هيتواصل معاك فوراً؟ 🙏';

// 3. Anti-spam delay
const minDelay = settings.reply_delay_min_sec || 5;
const maxDelay = settings.reply_delay_max_sec || 40;
const delaySeconds = Math.floor(Math.random() * (maxDelay - minDelay + 1)) + minDelay;

return [{
  json: {
    token: channel.token,
    page_id: channel.page_id,
    post_id: event.post_id,
    comment_id: event.comment_id,
    commenter_id: commenterId,
    commenter_name: commenterName,
    comment_text: commentText,

    system_prompt: systemPrompt,
    action_assets: actionAssets,
    fallback_dm_message: fallbackDmMessage,
    complaint_public_reply: complaintPublicReply,
    complaint_dm_message: complaintDmMessage,
    fixed_replies_enabled: fixedRepliesEnabled,
    normal_fixed_replies: normalFixedReplies,
    available_actions_text: actionsDescriptions,
    allowed_actions_keys: allowedActionKeys,
    reply_delay_sec: delaySeconds,
    ai_enabled: Boolean(settings.ai_enabled),
  }
}];

const item = $input.first();
let raw = '';
try { if (item.binary?.data) raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'); } catch (e) {}
let body = item.json.body;
if (!body || typeof body !== 'object' || !body.object) {
  try { body = JSON.parse(raw || '{}'); } catch (e) { body = {}; }
}

// Ignore anything not from a Facebook Page
if (body.object !== 'page') return [];

const signature = item.json.headers?.['x-hub-signature-256'] || '';
const out = [];

for (const entry of body.entry || []) {
  const page_id = String(entry.id);

  // 1. Post Comments
  for (const ch of entry.changes || []) {
    if (ch.field === 'feed' && ch.value?.item === 'comment' && ch.value?.verb === 'add') {
      out.push({
        json: {
          kind: 'comment',
          page_id,
          payload: ch.value,
          signature,
          raw_body: raw,
        },
      });
    }
  }

  // 2. Messenger Chats & Postbacks
  for (const m of entry.messaging || []) {
    out.push({
      json: {
        kind: 'messaging',
        page_id,
        payload: m,
        signature,
        raw_body: raw,
      },
    });
  }
}

return out;

const ev = $('Split Events').first().json;
const ch = $('Get Channel').first().json;
const sec = $input.first().json;

return [{
  json: {
    kind: ev.kind,
    channel: {
      id: ch.id,
      page_id: ch.external_id,
      name: ch.name,
      token: sec.access_token,
    },
    event: ev.payload,
  }
}];

const context = $('Build Event Context').first().json;
const rules = $input.all().map(i => i.json).filter(r => r && r.id);
const postSetting = $('Get Post Settings').first()?.json;
if (postSetting && postSetting.bot_enabled === false) {
  return [];
}
const commentText = (context.event?.message || '').toLowerCase().trim();
let matchedRule = null;
let isToxic = false;

// 1. Find active rule for this post
for (const rule of rules) {
  if (rule.is_active === false) continue;

  // Check toxic / forbidden words first
  if (Array.isArray(rule.delete_keywords) && rule.delete_keywords.length > 0) {
    const hasToxic = rule.delete_keywords.some(kw => kw && commentText.includes(kw.trim().toLowerCase()));
    if (hasToxic) {
      matchedRule = rule;
      isToxic = true;
      break;
    }
  }

  // Check trigger condition
  if (rule.trigger_type === 'any') {
    matchedRule = rule;
    break;
  } else if (rule.trigger_type === 'keywords' && Array.isArray(rule.keywords)) {
    const hasKeyword = rule.keywords.some(kw => kw && commentText.includes(kw.trim().toLowerCase()));
    if (hasKeyword) {
      matchedRule = rule;
      break;
    }
  }
}

// 2. If a rule matched
if (matchedRule) {
  if (isToxic) {
    return [{
      json: {
        rule_matched: true,
        action: 'delete',
        token: context.channel.token,
        page_id: context.channel.page_id,
        comment_id: context.event.comment_id,
        commenter_name: context.event?.from?.name || 'العميل',
        comment_text: context.event?.message || '',
        auto_delete: Boolean(matchedRule.auto_delete),
        should_hide: !Boolean(matchedRule.auto_delete),
        send_dm: Boolean(matchedRule.dm_enabled && matchedRule.dm_message),
        dm_message: matchedRule.dm_message || null,
        dm_buttons: Array.isArray(matchedRule.dm_buttons) ? matchedRule.dm_buttons : [],
      }
    }];
  }

  // Normal rule execution (single or randomized variations)
  const replies = Array.isArray(matchedRule.reply_variations) && matchedRule.reply_variations.length > 0
    ? matchedRule.reply_variations
    : [];
  const selectedReply = replies.length > 0
    ? replies[Math.floor(Math.random() * replies.length)]
    : null;

  return [{
    json: {
      rule_matched: true,
      action: 'normal',
      token: context.channel.token,
      page_id: context.channel.page_id,
      comment_id: context.event.comment_id,
      commenter_name: context.event?.from?.name || 'العميل',
      comment_text: context.event?.message || '',
      send_public_reply: Boolean(matchedRule.reply_enabled !== false && selectedReply),
      public_reply: selectedReply,
      comment_image_url: matchedRule.comment_image_url || null,
      auto_like: Boolean(matchedRule.like_comment !== false),
      send_dm: Boolean(matchedRule.dm_enabled && matchedRule.dm_message),
      dm_message: matchedRule.dm_message || null,
      dm_buttons: Array.isArray(matchedRule.dm_buttons) ? matchedRule.dm_buttons : [],
    }
  }];
}

// 3. No rule matched -> Proceed to AI branch!
return [{
  json: {
    rule_matched: false,
  }
}];

