} else if (inputItem.message?.content) {
  raw = typeof inputItem.message.content === 'string' ? inputItem.message.content : JSON.stringify(inputItem.message.content);
} else if (inputItem.decision || inputItem.action || inputItem.public_reply) {
  raw = JSON.stringify(inputItem);
} else {
  raw = JSON.stringify(inputItem);
}

// 1. Clean markdown blocks
raw = raw.replace(/```json/gi, "").replace(/```/g, "").trim();

// 2. Fixed messages from Dashboard settings
const dashboardFallbackDm = (prev.fallback_dm_message || "").trim() || "أهلاً بحضرتك يا فندم نورتنا! 🍗 تقدر تطلب أو تستفسر عن أي حاجة من هنا مباشرة 🛵";
const complaintPublicReply = (prev.complaint_public_reply || "").trim() || "بنعتذر جداً لحضرتك يا فندم، يهمنا رضاك وتم التواصل معاك على الخاص لحل المشكلة فوراً 🙏";
const complaintDmMessage = (prev.complaint_dm_message || "").trim() || "أهلاً بحضرتك يا فندم، بنعتذر جداً عن أي إزعاج. ممكن تبعتلنا رقم تليفونك وتفاصيل المشكلة وفريق خدمة العملاء هيتواصل معاك فوراً؟ 🙏";
const fixedRepliesEnabled = Boolean(prev.fixed_replies_enabled);
const normalFixedReplies = Array.isArray(prev.normal_fixed_replies) && prev.normal_fixed_replies.length > 0
  ? prev.normal_fixed_replies
  : ["أهلاً بحضرتك يا فندم في تشيكن مراعي! 🍗 تم إرسال كل التفاصيل في رسائل الصفحة 📩"];

const pickRandomNormalReply = () =>
  normalFixedReplies[Math.floor(Math.random() * normalFixedReplies.length)];

// 3. Extract JSON object
const match = raw.match(/\{[\s\S]*\}/);
let parsed = {};

if (!match) {
  const isDelete = raw.toUpperCase().includes("DELETE");
  parsed = {
    decision: isDelete ? "DELETE" : "KEEP",
    action: "normal",
    is_complaint: isDelete,
    public_reply: raw,
    dm_message: dashboardFallbackDm
  };
} else {
  let jsonString = match[0];
  let fixed = "";
  let inString = false;
  let escaped = false;

  for (let i = 0; i < jsonString.length; i++) {
    const ch = jsonString[i];
    if (!inString) {
      fixed += ch;
      if (ch === '"') inString = true;
    } else {
      if (escaped) {
        fixed += ch;
        escaped = false;
      } else if (ch === "\\") {
        fixed += ch;
        escaped = true;
      } else if (ch === '"') {
        fixed += ch;
        inString = false;
      } else if (ch === "\n") {
        fixed += "\\n";
      } else if (ch === "\r") {
        // ignore CR
      } else {
        fixed += ch;
      }
    }
  }

  try {
    parsed = JSON.parse(fixed);
  } catch (err) {
    try {
      parsed = JSON.parse(jsonString);
    } catch (err2) {
      parsed = {
        decision: "KEEP",
        action: "normal",
        is_complaint: false,
        public_reply: raw,
        dm_message: ""
      };
    }
  }
}

// 4. Case-insensitive DELETE check + negative comment keyword guard
const commentTextLower = String(prev.comment_text || "").toLowerCase();
const negativeKeywords = [
  "بارد", "ساقع", "وحش", "وحشه", "وحشة", "سيء", "سئ", "سيئه", "سيئة",
  "زفت", "مقرف", "معفن", "ريحة", "ريحه", "نيء", "مش مستوي", "محروق",
  "مزيت", "ناشف", "اتأخر", "اتاخر", "متأخر", "متاخر", "تأخير", "تاخير",
  "ناقص", "حرام عليكم", "نصب", "اسوأ", "أسوأ", "زبالة", "زباله"
];
const hasNegativeKeyword = negativeKeywords.some(kw => commentTextLower.includes(kw));
const rawDecision = String(parsed.decision || "").trim().toUpperCase();
const isComplaint = Boolean(parsed.is_complaint) || hasNegativeKeyword;
const isDeleteDecision = rawDecision === "DELETE" || isComplaint || hasNegativeKeyword;
const isKeep = !isDeleteDecision;

const action = String(parsed.action || "normal").toLowerCase().trim();

let finalPublicReply = "";
let finalDmMessage = complaintDmMessage;

if (isKeep) {
  if (fixedRepliesEnabled) {
    finalPublicReply = pickRandomNormalReply();
    finalDmMessage = dashboardFallbackDm;
  } else {
    finalPublicReply = (parsed.public_reply || "").trim() || pickRandomNormalReply();
    finalDmMessage = (parsed.dm_message && parsed.dm_message.trim().length > 0)
      ? parsed.dm_message.trim()
      : dashboardFallbackDm;
  }
} else {
  // DELETE path: never post a public reply, always prepare apology DM message
  finalPublicReply = "";
  finalDmMessage = (parsed.dm_message && parsed.dm_message.trim().length > 0)
    ? parsed.dm_message.trim()
    : complaintDmMessage;
}

return [{
  json: {
    token: prev.token,
    page_id: prev.page_id,
    post_id: prev.post_id,
    comment_id: prev.comment_id,
    commenter_id: prev.commenter_id,
    commenter_name: prev.commenter_name,
    comment_text: prev.comment_text,
    reply_delay_sec: prev.reply_delay_sec,

    // Decision & Action Fields
    decision: isKeep ? "KEEP" : "DELETE",
    action: action,
    is_complaint: isComplaint,
    public_reply: finalPublicReply,

    // Send DM
    send_dm: true,
    dm_message: finalDmMessage
  }
}];

