// Loop over all items
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // 'data' is the name of your binary property (from your screenshot)
  // We read the file buffer from n8n's internal storage
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  // Convert the buffer to a Base64 string and save it to a new JSON field
  item.json.audioBase64 = buffer.toString('base64');
}

return items;

// 1. قراءة بيانات العروض والفروع مباشرة من النود السابقة
const inputData = $input.first()?.json || {};
const offersList = Array.isArray(inputData.offers) ? inputData.offers : [];
const branchesList = Array.isArray(inputData.branches) ? inputData.branches : [];
const openComplaintsList = Array.isArray(inputData.open_complaints) ? inputData.open_complaints : [];

// استبعاد سجل صورة جميع العروض المجمعة (__ALL_OFFERS_IMAGE__) من النص المرسل للذكاء الاصطناعي
const visibleOffers = offersList.filter(o => o && o.title && o.title !== '__ALL_OFFERS_IMAGE__');

// 2. قراءة رسالة العميل وضمان تحويلها دائماً إلى String عادي
let rawMsg = null;
try {
  rawMsg = $('Edit Fields1')?.first()?.json?.usermessage;
} catch (e) {}

if (rawMsg == null) {
  try {
    rawMsg = $('Aggregate')?.first()?.json?.message;
} catch (e) {}
}

if (rawMsg == null) {
  try {
    rawMsg = $('Webhook1')?.first()?.json?.body?.entry?.[0]?.messaging?.[0]?.message?.text;
  } catch (e) {}
}

// تحويل أي مصفوفة (List) إلى String واحد مجمع بنظافة
const body = Array.isArray(rawMsg)
  ? rawMsg.filter(Boolean).map(m => (typeof m === 'object' ? JSON.stringify(m) : String(m))).join(" ").trim()
  : (rawMsg != null ? String(rawMsg).trim() : "");

// 3. تنسيق العروض بشكل عربي واضح ومحدد
let offersText = "لا توجد عروض ترويجية نشطة حالياً.";
if (visibleOffers.length > 0) {
  offersText = visibleOffers.map((o, idx) => {
    const price = o.price_after ? ` بسعر ${o.price_after} ج.م` + (o.price_before ? ` (بدلاً من ${o.price_before} ج.م)` : '') : '';
    const desc = o.description ? ` — ${o.description}` : '';
    return `${idx + 1}. [${o.title}]${price}${desc}`;
  }).join('\n');
}

// 4. تجميع وتنسيق الفروع ومناطق التوصيل
let branchesText = "خدمة التوصيل تغطي جميع الفروع.";
if (branchesList.length > 0) {
  const branchMap = {};
  for (const row of branchesList) {
    if (!row || !row.branch_name) continue;
    const bName = String(row.branch_name);
    if (!branchMap[bName]) {
      branchMap[bName] = {
        name: bName,
        address: row.branch_address || '',
        zones: []
      };
    }
    if (row.zone_name) {
      branchMap[bName].zones.push({
        zone: row.zone_name,
        fee: row.delivery_fee,
        time: row.estimated_delivery_time
      });
    }
  }

  branchesText = Object.values(branchMap).map(b => {
    let zonesStr = "التوصيل متاح لكافة المناطق";
    if (b.zones.length > 0) {
      zonesStr = b.zones.map(z => `${z.zone} (توصيل: ${z.fee} ج.م)`).join('، ');
    }
    return `📍 فرع: ${b.name} (${b.address || 'العنوان متاح لدى الفرع'})\n   مناطق التوصيل: ${zonesStr}`;
  }).join('\n');
}

// 5. إرجاع النتيجة للذكاء الاصطناعي
return [
  {
    json: {
      body: body, // نص String مؤكد 100%
      offers: offersText,
      branches: branchesText,
      raw_offers: offersList,
      raw_branches: branchesList,
      raw_open_complaints: openComplaintsList
    }
  }
];

// 1. Read the AI Agent's actual output (.output)
const raw = $input.first()?.json?.output 
         || $input.first()?.json?.text 
         || $input.first()?.json?.content 
         || "";

// Remove any markdown ```json wrapping
