  for (let i = 0; i < candidate.length; i++) {
    const ch = candidate[i];
    if (!inString) {
      fixed += ch;
      if (ch === '"') inString = true;
    } else {
      if (escaped) {
        fixed += ch;
        escaped = false;
      } else if (ch === "\\") {
        fixed += ch;
        escaped = true;
      } else if (ch === '"') {
        fixed += ch;
        inString = false;
      } else if (ch === "\n") {
        fixed += "\\n";
      } else if (ch === "\r") {
        // ignore CR
      } else {
        fixed += ch;
      }
    }
  }

  try {
    return JSON.parse(fixed);
  } catch (e1) {
    try {
      return JSON.parse(candidate);
    } catch (e2) {
      // Regex fallback so raw JSON is NEVER sent to the customer
      const intentMatch = candidate.match(/"intent"\s*:\s*"([^"]+)"/);
      const offerMatch = candidate.match(/"offer_name"\s*:\s*"([^"]+)"/);
      const replyMatch = candidate.match(/"reply"\s*:\s*"([\s\S]*?)"\s*(?:,\s*"(?:offer_name|order_details|complaint_details)"|\s*\})/);
      const fallbackReply = replyMatch
        ? replyMatch[1].replace(/\\n/g, "\n")
        : text.replace(/^\s*\{[\s\S]*?"reply"\s*:\s*"/, "").replace(/"\s*(?:,\s*"(?:order_details|complaint_details)"[\s\S]*)?\}\s*$/, "");
      return {
        intent: intentMatch ? intentMatch[1] : "normal",
        offer_name: offerMatch ? offerMatch[1] : null,
        reply: fallbackReply
      };
    }
  }
}

const parsed = parseAiJson(cleaned);
let intent = parsed.intent || "normal";
const offerName = parsed.offer_name ? String(parsed.offer_name).trim() : null;
let order = null;
let complaint = null;
let offerImageUrl = null;

// 2. Fetch raw database branches, offers & open complaints from Code1
let rawOffers = [];
let rawBranches = [];
let rawOpenComplaints = [];
try {
  const code1Data = $('Code1').first()?.json;
  rawOffers = code1Data?.raw_offers || [];
  rawBranches = code1Data?.raw_branches || [];
  rawOpenComplaints = code1Data?.raw_open_complaints || [];
} catch (e) {}

// 2b. Match Offer Image URL for single_offer or all_offers
// Note: public.offers stores images in `banner_url`, and the combined all-offers image in row `title === '__ALL_OFFERS_IMAGE__'`
const allOffersRecord = rawOffers.find(of => of && of.title === '__ALL_OFFERS_IMAGE__');
let allOffersBannerUrl = allOffersRecord?.banner_url || allOffersRecord?.image_url || null;
if (!allOffersBannerUrl) {
  try {
    allOffersBannerUrl = $('bot settings').first()?.json?.all_offers_image_url || null;
  } catch (e) {}
}

const realOffers = rawOffers.filter(of => of && of.title && of.title !== '__ALL_OFFERS_IMAGE__');

if (intent === 'single_offer') {
  if (offerName) {
    const target = offerName.toLowerCase();
    const matchedOffer = realOffers.find(of => (
      of.title.trim().toLowerCase() === target ||
      of.title.trim().toLowerCase().includes(target) ||
      target.includes(of.title.trim().toLowerCase())
    ));
    if (matchedOffer) {
      offerImageUrl = matchedOffer.banner_url || matchedOffer.image_url || allOffersBannerUrl;
    } else {
      offerImageUrl = allOffersBannerUrl;
    }
  } else {
    offerImageUrl = allOffersBannerUrl;
  }
} else if (intent === 'all_offers') {
  offerImageUrl = allOffersBannerUrl;
}

// 3. Strict Rule: Block order creation between 3:00 AM and 11:00 AM Cairo time
const cairoHour = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'Africa/Cairo', hour: 'numeric', hour12: false }).format(new Date())) % 24;
const isClosedForOrders = cairoHour >= 3 && cairoHour < 11;
if (intent === 'order' && isClosedForOrders) {
  intent = 'normal';
  order = null;
  parsed.reply = 'بنعتذر لحضرتك جداً يا فندم، مواعيد عمل المطعم واستقبال الأوردرات يومياً من الساعة 11:00 صباحاً حتى الساعة 3:00 فجراً 🕒. تنورنا بطلبك ابتداءً من الساعة 11 صباحاً، وتحت أمرك حالياً لو عندك أي استفسار عن المنيو أو العروض!';
}

// Only process and match order if intent is 'order'
if (intent === 'order' && parsed.order_details) {
  const o = parsed.order_details;
  let matchedBranchId = null;
  let matchedOfferId = null;
  let matchedDeliveryFee = 0;

  // Match Branch Name -> branch_id UUID
  const branchName = String(o.branch_name || "").trim().toLowerCase();
  if (branchName) {
    const foundBranch = rawBranches.find(b => b.branch_name && (
      b.branch_name.toLowerCase().includes(branchName) || 
      branchName.includes(b.branch_name.toLowerCase())
    ));
    if (foundBranch) matchedBranchId = foundBranch.branch_id;
  }

  // Match Offer Title -> offer_id UUID
  const offerTitle = String(o.offer_title || "").trim().toLowerCase();
  if (offerTitle) {
    const foundOffer = realOffers.find(of => (
      of.title.toLowerCase().includes(offerTitle) || 
      offerTitle.includes(of.title.toLowerCase())
    ));
    if (foundOffer) matchedOfferId = foundOffer.id;
  }

  // Match Delivery Zone -> delivery_fee
  const zoneName = String(o.delivery_zone || "").trim().toLowerCase();
  if (zoneName) {
    const foundZone = rawBranches.find(b => b.zone_name && (
      b.zone_name.toLowerCase().includes(zoneName) || 
      zoneName.includes(b.zone_name.toLowerCase())
    ));
    if (foundZone) {
      matchedDeliveryFee = Number(foundZone.delivery_fee) || 0;
      matchedBranchId = foundZone.branch_id;
    }
  }

  const normalizedItems = (Array.isArray(o.items) ? o.items : []).map(item => {
    const qty = Number(item.qty) || Number(item.quantity) || 1;
    let unitPrice = Number(item.price) || Number(item.unit_price) || 0;
    if (unitPrice === 0 && item.name) {
      const iName = String(item.name).trim().toLowerCase();
      const matchedOff = realOffers.find(of => (
        of.title.toLowerCase().includes(iName) || iName.includes(of.title.toLowerCase())
      ));
      if (matchedOff) unitPrice = Number(matchedOff.price_after) || 0;
    }
    const totalPrice = Number(item.total_price) || (unitPrice * qty);
    return {
      name: item.name || "وجبة",
      qty: qty,
      price: unitPrice,
      unit_price: unitPrice,
      total_price: totalPrice,
      notes: item.notes || ""
    };
  });

  const itemsSubtotal = normalizedItems.reduce((sum, it) => sum + it.total_price, 0);
  const totalAmount = Number(o.total_amount) || 0;
  let finalDeliveryFee = Number(o.delivery_fee) || matchedDeliveryFee || 0;
  if (finalDeliveryFee === 0 && totalAmount > 0 && itemsSubtotal > 0 && totalAmount > itemsSubtotal) {
    finalDeliveryFee = totalAmount - itemsSubtotal;
  }
  const finalSubtotal = itemsSubtotal > 0
    ? itemsSubtotal
    : Math.max(0, totalAmount - finalDeliveryFee);

  if (normalizedItems.length === 1 && normalizedItems[0].unit_price === 0 && finalSubtotal > 0) {
    normalizedItems[0].unit_price = finalSubtotal / normalizedItems[0].qty;
    normalizedItems[0].price = normalizedItems[0].unit_price;
    normalizedItems[0].total_price = finalSubtotal;
  }

  order = {
    branch_name: o.branch_name || "",
    branch_id: matchedBranchId,
    offer_title: o.offer_title || "",
    offer_id: matchedOfferId,
    delivery_zone: o.delivery_zone || "",
    delivery_fee: finalDeliveryFee,
    subtotal: finalSubtotal,
    items: normalizedItems,
    total_amount: totalAmount || (finalSubtotal + finalDeliveryFee),
    customer_name: o.customer_name || "",
    phone: o.phone || "",
    address: o.address || "",
    notes: o.notes || ""
  };
}

// 4. Read context and contact IDs
let psid = "";
let page_id = "";
let token = "";
let contact_id = "";

try {
  const context = $('Parse Messenger Event').first()?.json;
  psid = context?.psid || "";
  page_id = context?.page_id || "";
  token = context?.token || "";
} catch (e) {}

try {
  contact_id = $('Edit Fields4').first()?.json?.contact_uuid 
            || $('Edit Fields1').first()?.json?.contact_uuid 
            || "";
} catch (e) {}

// 5. Strict Rule: Only process complaint if intent is 'complaint' AND valid phone + issue exist AND no recent open complaint exists for this contact
if (intent === 'complaint') {
  const cPhone = String(parsed.complaint_details?.phone || "").trim();
  const cIssue = String(parsed.complaint_details?.issue || "").trim();
  const alreadyHasOpenComplaint = contact_id && rawOpenComplaints.some(c => c && c.contact_id === contact_id);

  if (!cPhone || !cIssue || alreadyHasOpenComplaint) {
    // Downgrade to normal so Switch1 does NOT create an empty or duplicate complaint ticket
    intent = "normal";
    complaint = null;
  } else {
    complaint = {
      phone: cPhone,
      issue: cIssue
    };
  }
}

return [{
  json: {
    intent: intent,
    offer_name: offerName,
    offer_image_url: offerImageUrl,
    reply: parsed.reply || cleaned,
    order_details: order,
    complaint_details: complaint,
    psid: psid,
    page_id: page_id,
    token: token,
    contact_id: contact_id
  }
}];

// 1. Get the new order ID created by Supabase
const orderId = $input.first().json.id;

// 2. Get the items array from Code in JavaScript3
const orderDetails = $('Code in JavaScript3').first().json.order_details || {};
const items = orderDetails.items || [];
const orderSubtotal = Number(orderDetails.subtotal) || Math.max(0, (Number(orderDetails.total_amount) || 0) - (Number(orderDetails.delivery_fee) || 0));

// Fallback if no specific items were listed
if (items.length === 0) {
  return [{
    json: {
      order_id: orderId,
      item_name: "طلب وجبات متنوعة",
      quantity: 1,
      unit_price: orderSubtotal,
      total_price: orderSubtotal,
      notes: ""
    }
  }];
}

// 3. Convert each meal into a separate row for Supabase
return items.map(item => {
  const qty = Number(item.qty) || Number(item.quantity) || 1;
  let unitPrice = Number(item.price) || Number(item.unit_price) || 0;
  if (unitPrice === 0 && items.length === 1 && orderSubtotal > 0) {
    unitPrice = orderSubtotal / qty;
  }
  const totalPrice = Number(item.total_price) || (unitPrice * qty);
  return {
    json: {
      order_id: orderId,
      item_name: item.name || "وجبة",
      quantity: qty,
      unit_price: unitPrice,
      total_price: totalPrice,
      notes: item.notes || ""
    }
  };
});

